Path("src/validation/uxr0-replacement-qualification.ts").write_text("""/**\n * UXR0 replacement A/B evidence contract.\n *\n * The comparator establishes whether two observations are legitimately\n * comparable and exposes raw candidate-minus-baseline deltas. It deliberately\n * does not contain adoption thresholds or an automatic promotion decision.\n */\n\nexport type Uxr0QualificationProfileKind =\n  | 'functional-5m'\n  | 'resource-trend-30m'\n  | 'sustained-60m';\n\nexport interface Uxr0ReplacementScenarioIdentity {\n  deviceTarget: string;\n  deviceRuntimeId: string;\n  datasetFingerprint: string;\n  sourceRowCount: number;\n  taskScriptId: string;\n  representationId: string;\n  representationStateHash: string;\n  profileKind: Uxr0QualificationProfileKind;\n}\n\nexport interface Uxr0ReplacementMetrics {\n  frameP95Ms: number | null;\n  frameP99Ms: number | null;\n  drawCallsMax: number | null;\n  sceneObjectCountEnd: number | null;\n  jsHeapPeakBytes: number | null;\n  wasmPeakBytes: number | null;\n  workerOutboundPayloadBytesEstimate: number | null;\n  workerInboundPayloadBytesEstimate: number | null;\n  bundleBytes: number | null;\n  dependencyCount: number | null;\n}\n\nexport interface Uxr0ReplacementObservation {\n  schemaVersion: 1;\n  variant: 'baseline' | 'candidate';\n  implementationId: string;\n  buildHash: string;\n  scenario: Uxr0ReplacementScenarioIdentity;\n  semanticDigest: string;\n  interactionDigest: string;\n  metrics: Uxr0ReplacementMetrics;\n}\n\nexport interface Uxr0ReplacementComparison {\n  schemaVersion: 1;\n  disposition: 'not-comparable' | 'evidence-comparable';\n  identityMismatches: string[];\n  parityIssues: string[];\n  deltas: Uxr0ReplacementMetrics;\n}\n\nconst SCENARIO_FIELDS = [\n  'deviceTarget',\n  'deviceRuntimeId',\n  'datasetFingerprint',\n  'sourceRowCount',\n  'taskScriptId',\n  'representationId',\n  'representationStateHash',\n  'profileKind',\n] as const satisfies readonly (keyof Uxr0ReplacementScenarioIdentity)[];\n\nconst METRIC_FIELDS = [\n  'frameP95Ms',\n  'frameP99Ms',\n  'drawCallsMax',\n  'sceneObjectCountEnd',\n  'jsHeapPeakBytes',\n  'wasmPeakBytes',\n  'workerOutboundPayloadBytesEstimate',\n  'workerInboundPayloadBytesEstimate',\n  'bundleBytes',\n  'dependencyCount',\n] as const satisfies readonly (keyof Uxr0ReplacementMetrics)[];\n\nfunction delta(baseline: number | null, candidate: number | null): number | null {\n  return baseline === null || candidate === null ? null : candidate - baseline;\n}\n\nfunction nonEmpty(value: string): boolean {\n  return value.trim().length > 0;\n}\n\nexport function compareUxr0ReplacementEvidence(\n  baseline: Uxr0ReplacementObservation,\n  candidate: Uxr0ReplacementObservation\n): Uxr0ReplacementComparison {\n  const identityMismatches: string[] = [];\n  const parityIssues: string[] = [];\n\n  if (baseline.schemaVersion !== 1 || candidate.schemaVersion !== 1) {\n    identityMismatches.push('schemaVersion');\n  }\n  if (baseline.variant !== 'baseline') identityMismatches.push('baseline.variant');\n  if (candidate.variant !== 'candidate') identityMismatches.push('candidate.variant');\n  if (!nonEmpty(baseline.implementationId) || !nonEmpty(candidate.implementationId)) {\n    identityMismatches.push('implementationId');\n  }\n  if (!nonEmpty(baseline.buildHash) || !nonEmpty(candidate.buildHash)) {\n    identityMismatches.push('buildHash');\n  }\n  if (!Number.isSafeInteger(baseline.scenario.sourceRowCount) || baseline.scenario.sourceRowCount <= 0) {\n    identityMismatches.push('baseline.sourceRowCount');\n  }\n  if (!Number.isSafeInteger(candidate.scenario.sourceRowCount) || candidate.scenario.sourceRowCount <= 0) {\n    identityMismatches.push('candidate.sourceRowCount');\n  }\n\n  for (const field of SCENARIO_FIELDS) {\n    if (baseline.scenario[field] !== candidate.scenario[field]) {\n      identityMismatches.push(`scenario.${field}`);\n    }\n  }\n\n  if (!nonEmpty(baseline.semanticDigest) || baseline.semanticDigest !== candidate.semanticDigest) {\n    parityIssues.push('semanticDigest');\n  }\n  if (!nonEmpty(baseline.interactionDigest) || baseline.interactionDigest !== candidate.interactionDigest) {\n    parityIssues.push('interactionDigest');\n  }\n\n  const deltas = Object.fromEntries(\n    METRIC_FIELDS.map((field) => [field, delta(baseline.metrics[field], candidate.metrics[field])])\n  ) as unknown as Uxr0ReplacementMetrics;\n\n  return {\n    schemaVersion: 1,\n    disposition:\n      identityMismatches.length === 0 && parityIssues.length === 0\n        ? 'evidence-comparable'\n        : 'not-comparable',\n    identityMismatches,\n    parityIssues,\n    deltas,\n  };\n}\n""")

Path("tests/uxr0-worker-transfer-diagnostics.test.ts").write_text("""import { describe, expect, it } from 'vitest';\nimport {\n  WorkerAnalyticalPort,\n  type WorkerTransport,\n} from '../src/atlas/ports/WorkerAnalyticalPort.ts';\nimport type {\n  AnalyticalDatasetRegistration,\n  AnalyticalExecutionRequest,\n  AnalyticalExecutionResult,\n  AnalyticalWorkerDiagnostic,\n} from '../src/atlas/ports/AnalyticalExecutionPort.ts';\n\nfunction diagnostic(id: string, phase: 'registration' | 'execution'): AnalyticalWorkerDiagnostic {\n  return {\n    schemaVersion: 1,\n    phase,\n    id,\n    timingMs: { total: 1 },\n    wasmBytes: { before: 0, afterKernel: 0, afterMaterialize: 0 },\n    hostBufferAllocations: { before: 0, after: 0 },\n  };\n}\n\nfunction transportHarness(): WorkerTransport & {\n  posted: unknown[];\n  emit(data: unknown): void;\n} {\n  let onmessage: ((event: MessageEvent) => void) | null = null;\n  const posted: unknown[] = [];\n  return {\n    posted,\n    get onmessage() {\n      return onmessage;\n    },\n    set onmessage(value) {\n      onmessage = value;\n    },\n    onerror: null,\n    onmessageerror: null,\n    postMessage(message: unknown) {\n      posted.push(message);\n    },\n    emit(data: unknown) {\n      onmessage?.(new MessageEvent('message', { data }));\n    },\n  };\n}\n\ndescribe('UXR0 Worker transfer diagnostics', () => {\n  it('records exact binary registration bytes while labelling total payload volume as an estimate', async () => {\n    const transport = transportHarness();\n    const port = new WorkerAnalyticalPort(transport);\n    const registration: AnalyticalDatasetRegistration = {\n      registrationId: 'reg-uxr0',\n      generation: 1,\n      dataset: { fingerprint: 'fp-uxr0', version: 1 },\n      payload: { type: 'typed', data: new Uint8Array(64), name: 'typed-fixture' },\n    };\n\n    const promise = port.registerDataset(registration);\n    transport.emit({\n      type: 'REGISTERED',\n      registrationId: registration.registrationId,\n      generation: 1,\n      datasetVersion: 1,\n      datasetFingerprint: 'fp-uxr0',\n      diagnostic: diagnostic(registration.registrationId, 'registration'),\n    });\n    await promise;\n\n    const sample = port.drainDiagnostics()[0];\n    expect(sample.transportBytes?.measurementBasis).toBe(\n      'utf8-json-estimate+exact-binary-byte-length'\n    );\n    expect(sample.transportBytes?.exactBinaryOutboundBytes).toBe(64);\n    expect(sample.transportBytes?.outboundPayloadBytesEstimate).toBeGreaterThanOrEqual(64);\n    expect(sample.transportBytes?.inboundPayloadBytesEstimate).toBeGreaterThan(0);\n  });\n\n  it('measures execution request/response payloads only when a Worker diagnostic is emitted', async () => {\n    const transport = transportHarness();\n    const port = new WorkerAnalyticalPort(transport);\n    const request: AnalyticalExecutionRequest = {\n      requestId: 'exec-uxr0',\n      operation: 'statistics',\n      generation: 1,\n      dataset: { fingerprint: 'fp-uxr0', version: 1 },\n      params: { field: 'value' },\n    };\n    const promise = port.execute(request);\n    const result: AnalyticalExecutionResult = {\n      requestId: request.requestId,\n      generation: 1,\n      datasetVersion: 1,\n      datasetFingerprint: 'fp-uxr0',\n      value: { mean: 42, count: 100 },\n    };\n    transport.emit({\n      type: 'RESULT',\n      result,\n      diagnostic: diagnostic(request.requestId, 'execution'),\n    });\n    await promise;\n\n    const sample = port.drainDiagnostics()[0];\n    expect(sample.transportBytes?.exactBinaryOutboundBytes).toBe(0);\n    expect(sample.transportBytes?.outboundPayloadBytesEstimate).toBeGreaterThan(0);\n    expect(sample.transportBytes?.inboundPayloadBytesEstimate).toBeGreaterThan(0);\n  });\n});\n""")

Path("tests/uxr0-replacement-qualification.test.ts").write_text("""import { describe, expect, it } from 'vitest';\nimport {\n  compareUxr0ReplacementEvidence,\n  type Uxr0ReplacementObservation,\n} from '../src/validation/uxr0-replacement-qualification.ts';\n\nfunction observation(\n  variant: 'baseline' | 'candidate',\n  overrides: Partial<Uxr0ReplacementObservation> = {}\n): Uxr0ReplacementObservation {\n  return {\n    schemaVersion: 1,\n    variant,\n    implementationId: variant === 'baseline' ? 'local-pointer' : 'candidate-pointer',\n    buildHash: variant === 'baseline' ? 'build-a' : 'build-b',\n    scenario: {\n      deviceTarget: 'META_QUEST_3S',\n      deviceRuntimeId: 'quest-runtime-1',\n      datasetFingerprint: 'dataset-fp',\n      sourceRowCount: 100_000,\n      taskScriptId: 'select-drag-return-v1',\n      representationId: 'aggregate-volume',\n      representationStateHash: 'representation-state-a',\n      profileKind: 'functional-5m',\n    },\n    semanticDigest: 'semantic-same',\n    interactionDigest: 'interaction-same',\n    metrics: {\n      frameP95Ms: variant === 'baseline' ? 14 : 12,\n      frameP99Ms: variant === 'baseline' ? 18 : 16,\n      drawCallsMax: variant === 'baseline' ? 40 : 32,\n      sceneObjectCountEnd: 80,\n      jsHeapPeakBytes: variant === 'baseline' ? 1_000 : 900,\n      wasmPeakBytes: 2_000,\n      workerOutboundPayloadBytesEstimate: variant === 'baseline' ? 500 : 450,\n      workerInboundPayloadBytesEstimate: 300,\n      bundleBytes: variant === 'baseline' ? 100_000 : 110_000,\n      dependencyCount: variant === 'baseline' ? 10 : 11,\n    },\n    ...overrides,\n  };\n}\n\ndescribe('UXR0 replacement qualification contract', () => {\n  it('permits different build hashes but only returns comparable evidence and raw deltas', () => {\n    const comparison = compareUxr0ReplacementEvidence(\n      observation('baseline'),\n      observation('candidate')\n    );\n    expect(comparison.disposition).toBe('evidence-comparable');\n    expect(comparison.identityMismatches).toEqual([]);\n    expect(comparison.parityIssues).toEqual([]);\n    expect(comparison.deltas.frameP95Ms).toBe(-2);\n    expect(comparison.deltas.bundleBytes).toBe(10_000);\n    expect(comparison.deltas.dependencyCount).toBe(1);\n    expect(comparison).not.toHaveProperty('adopt');\n    expect(comparison).not.toHaveProperty('winner');\n  });\n\n  it('fails closed when device/dataset/task/representation identity is not the same', () => {\n    const candidate = observation('candidate');\n    candidate.scenario = { ...candidate.scenario, datasetFingerprint: 'different-dataset' };\n    const comparison = compareUxr0ReplacementEvidence(observation('baseline'), candidate);\n    expect(comparison.disposition).toBe('not-comparable');\n    expect(comparison.identityMismatches).toContain('scenario.datasetFingerprint');\n  });\n\n  it('refuses comparability when semantic or interaction parity digests diverge', () => {\n    const candidate = observation('candidate', {\n      semanticDigest: 'semantic-different',\n      interactionDigest: 'interaction-different',\n    });\n    const comparison = compareUxr0ReplacementEvidence(observation('baseline'), candidate);\n    expect(comparison.disposition).toBe('not-comparable');\n    expect(comparison.parityIssues).toEqual(['semanticDigest', 'interactionDigest']);\n  });\n});\n""")

